/// Canonical declaration helper
#[macro_export]
macro_rules! canonical_decl {
    ($item:expr) => {{
        let minimal_form = format!("{:?}", $item)
            .chars()
            .filter(|c| c.is_alphanumeric() || *c == '_')
            .collect::<String>();
        
        use std::hash::{Hash, Hasher};
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        minimal_form.hash(&mut hasher);
        let hash = hasher.finish();
        
        (minimal_form, format!("{:x}", hash))
    }};
}
